window.kbPageData["views/entry/k-cf7af90827570bfd"] = {"key":"entry/k-cf7af90827570bfd","state":{"route":"entry/k-cf7af90827570bfd"},"node":{"id":"k-cf7af90827570bfd","mode":"k","title":"加快高水平科技自立自强","type":"概念与词义","domain":"科技","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["industry","innovation"],"主类":["概念与词义"],"出处性质":["报告摘登","机构注释"],"学科":["科技"],"时间索引":["年度事件或数据"],"来源主题":["产业、科技与对外开放","年度政府工作"],"资料类别":["时政","非时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"推动科技创新和产业创新深度融合。建设北京（京津冀）、上海（长三角）、粤港澳\n大湾区国际科技创新中心，打造世界级科技创新策源地。强化企业创新主体地位，支持科\n技领军企业牵头组建创新联合体，提高承担国家重大科技项目比例。加强中试验证平台建设，\n完善新兴领域知识产权保护制度，加快重大科技成果高效转化应用。…","sources":[{"id":"4426c59af6105c80","label":"加快高水平科技自立自强","topic":"年度政府工作","category":"时政","text":"推动科技创新和产业创新深度融合。建设北京（京津冀）、上海（长三角）、粤港澳\n大湾区国际科技创新中心，打造世界级科技创新策源地。强化企业创新主体地位，支持科\n技领军企业牵头组建创新联合体，提高承担国家重大科技项目比例。加强中试验证平台建设，\n完善新兴领域知识产权保护制度，加快重大科技成果高效转化应用。加强科技创新全链条全\n生命周期金融服务，对关键核心技术领域的科技型企业，常态化实施上市融资、并购重组“绿\n色通道”机制，以科技金融支持创新创造。\n一体推进教育科技人才发展。建立健全一体推进的协调机制，强化规划衔接、政策协同、\n资源统筹、评价联动。完善人才培养与经济社会发展需要适配机制，分类推进高校改革，\n动态调整学科专业，启动新一轮“双一流”①建设，建设国家交叉学科中心，加大拔尖创新\n人才自主培养力度。加快建设国家战略人才力量，加强一流科技领军人才和青年人才引育，\n推进卓越工程师、大国工匠、高技能人才培养。高标准推进人才高地和人才平台建设，促\n进人才区域协调发展。深化人才发展体制机制改革，完善以创新能力、质量、实效、贡献为\n导向的评价体系，畅通人才交流通道，促进各类人才竞相成长、各展其能。","source":{"doc":"6cbfb01fe723bba64b75","first":27,"last":27,"page":27,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"08fbc6d8405a3842","label":"高水平科技自立自强","topic":"产业、科技与对外开放","category":"非时政","text":"4.高水平科技自立自强\n在关键核心技术领域实现自主可控，不依赖外部技术供给，同时具备持续创新能力，能\n够引领科技发展方向，为经济社会发展提供坚实科技支撑，是国家发展的战略支撑。","source":{"doc":"6cbfb01fe723bba64b75","first":17,"last":17,"page":17,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"},{"id":"a68d785a35e10e78","label":"加快高水平科技自立自强","topic":"年度政府工作","category":"时政","text":"（三）加快高水平科技自立自强。抓住新一轮科技革命和产业变革历史机遇，全面增\n强自主创新能力，为高质量发展①提供科技支撑。\n加强原始创新和关键核心技术攻关。发挥新型举国体制②优势，全链条推进关键核心技\n术攻关，组织实施好重大科技项目，强化战略前沿领域布局，产出更多原创性成果。继续提\n高基础研究投入比重，加大长期稳定支持。统筹国家战略科技力量建设，深化科研院所改革，\n加强国家实验室和重大科技任务、重大科技基础设施统筹部署，全面强化科技基础条件自主\n保障。加强科学技术普及。弘扬科学家精神③，深化科技评价体系改革，优化有利于原创性、\n颠覆性创新的环境。","source":{"doc":"6cbfb01fe723bba64b75","first":26,"last":27,"page":26,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"innovation","title":"科技创新与科研组织"},{"slug":"industry","title":"产业升级与新质生产力"}],"units":{"k-cf7af90827570bfd":[]}};
